 "content": "def transform(grid):
    """Copy the marked shape onto every translated occurrence in zero cells."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row}
    marker = max(colors)
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker]
    if not cells:
        return g
    minr = min(r for r, _ in cells)
    maxr = max(r for r, _ in cells)
    minc = min(c for _, c in cells)
    maxc = max(c for _, c in cells)
    shape = [(r - minr, c - minc) for r, c in cells]
    for r0 in range(h - (maxr - minr + 1) + 1):
        for c0 in range(w - (maxc - minc + 1) + 1):
            if all(g[r0 + dr][c0 + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    g[r0 + dr][c0 + dc] = marker
    return g
